                  </Pie>
                  <Tooltip
                    formatter={(v, _n, p) => [
                      fmtPct(Number(v), 1),
                      p.payload.label,
                    ]}
                  />
                </PieChart>
              </ResponsiveContainer>
            </div>
            <div className="mt-2 flex flex-wrap justify-center gap-3 text-xs text-slate-600">
              {TOP3_COMPOSITION.map((d) => (
                <span key={d.id} className="inline-flex items-center gap-1.5">
