                  layout="vertical"
                  margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis type="number" tick={{ fontSize: 11 }} unit="%" />
                  <YAxis
                    type="category"
                    dataKey="short"
                    width={36}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip
                    formatter={(v, _n, p) => [
                      `${fmtPct(Number(v), 1)} of GDP ?? ${fmtBn(p.payload.amountBn, 1)}`,
                      p.payload.label,
                    ]}
                  />
                  <Bar dataKey="remittanceGdpPct" radius={[0, 4, 4, 0]}>
                    {dependenceBars.map((r) => (
                      <Cell key={r.id} fill={r.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Host public-pension burdens"
            subtitle={`Italy ${fmtPct(HEADLINE.top1PensionGdpPct, 1)} of GDP ??? ${HEADLINE.italyVsOecdMultiple}?? OECD avg`}
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={pensionBars}
                  layout="vertical"
                  margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis type="number" tick={{ fontSize: 11 }} unit="%" />
                  <YAxis
                    type="category"
                    dataKey="short"
                    width={36}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip
                    formatter={(v, _n, p) => [
                      `${fmtPct(Number(v), 1)} of GDP`,
                      p.payload.label,
                    ]}
                  />
                  <Bar dataKey="pensionGdpPct" radius={[0, 4, 4, 0]}>
                    {pensionBars.map((r) => (
                      <Cell key={r.id} fill={r.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Dual ledger: age ?? remittance GDP share"
            subtitle="Aging hosts (low remittance %) vs remittance origins (high remittance %)"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ScatterChart margin={{ top: 12, right: 16, left: 8, bottom: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    dataKey="x"
                    name="Old-age dep."
                    tick={{ fontSize: 11 }}
                    domain={[0, 60]}
                    label={{
                      value: "Old-age dependency",
                      position: "insideBottom",
                      offset: -2,
                      fontSize: 11,
                    }}
                  />
                  <YAxis
                    type="number"
                    dataKey="y"
                    name="Remit % GDP"
                    tick={{ fontSize: 11 }}
                    domain={[0, 50]}
                    label={{
                      value: "Remittance % GDP",
                      angle: -90,
                      position: "insideLeft",
                      fontSize: 11,
                    }}
                  />
                  <ZAxis type="number" dataKey="z" range={[60, 400]} />
                  <Tooltip
                    cursor={{ strokeDasharray: "3 3" }}
                    formatter={(v, name) => {
                      if (name === "x") return [Number(v), "Old-age dep."];
                      if (name === "y") return [fmtPct(Number(v), 1), "Remit % GDP"];
                      return [v, name];
                    }}
                    labelFormatter={(_l, payload) =>
                      payload?.[0]?.payload?.label ?? ""
                    }
                  />
                  <Scatter data={dualScatter}>
                    {dualScatter.map((d) => (
                      <Cell key={d.id} fill={d.fill} />
                    ))}
                  </Scatter>
                </ScatterChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
    </div>
  );
}

